func (s *TemplateSplitService) EndTemplateFromDate(ctx context.Context, in timetable.EndTemplateCommand) (*timetable.EndTemplateResult, error) {
	if err := validateTemplateEndInput(in, s.deps.Today()); err != nil {
		return nil, err
	}
	tenantID := tenant.FromContext(ctx)
	if tenantID <= 0 {
		return nil, &ports.ScheduleError{Op: "end template", Err: errors.New("no tenant in context")}
	}
	if _, ok := tenant.TransactionFromContext(ctx); !ok && s.runInTx != nil {
		return s.endFromDateWithTransaction(ctx, in, tenantID)
	}
	return s.endFromDateInTransaction(ctx, in, tenantID)
}

